# Print detailed info: start events from 798, events where receiver==131, and events reachable from start event within one hop window
source=798
target=131
start=13902
end=33101
max_gap=600

E=[(u,v,t) for (u,v,t) in events if start<=t<=end]
print('total events in window', len(E))

# list start events
for idx,(u,v,t) in enumerate(E):
    if u==source:
        print('start_event_idx', idx, (u,v,t))
        start_idx=idx
        start_time=t

# list target receiver events
count=0
for idx,(u,v,t) in enumerate(E):
    if v==target:
        print('target_recv_idx', idx, (u,v,t))
        count+=1
print('target_recv_count', count)

# show events where sender == receiver of start_event and within (t, t+max_gap]
recv = E[start_idx][1]
print('start_event receiver', recv)
print('start_time', start_time)
for idx,(u,v,t) in enumerate(E):
    if u==recv and start_time < t <= start_time+max_gap:
        print('next_event_candidate', idx, (u,v,t))

# show chain up to length 4 via BFS on event indices
from collections import deque
# build sender_events
sender_events = {}
for idx,(u,v,t) in enumerate(E):
    sender_events.setdefault(u,[]).append((t,idx))
for u in sender_events:
    sender_events[u].sort()

# build next edges
n=len(E)
nexts=[[] for _ in range(n)]
import bisect
for i,(u,v,t) in enumerate(E):
    lst = sender_events.get(v,[])
    if not lst: continue
    times=[item[0] for item in lst]
    lo=bisect.bisect_right(times,t)
    hi=bisect.bisect_right(times,t+max_gap)
    for k in range(lo,hi):
        nexts[i].append(lst[k][1])

# BFS from start_idx
paths=[]
q=deque([(start_idx,[start_idx])])
while q and len(paths)<20:
    i,path=q.popleft()
    if E[i][1]==target:
        paths.append(path)
        continue
    if len(path)>=6: continue
    for j in nexts[i]:
        if j in path: continue
        q.append((j,path+[j]))

print('found paths count', len(paths))
for p in paths:
    print('path(len=%d)'%len(p))
    for idx in p:
        print(' ', idx, E[idx])

# print earliest arrival method outputs: earliest dict
# Compute earliest arrival as before
earliest={}
pred={}
for idx,(u,v,t) in enumerate(E):
    if u==source:
        if v not in earliest or t<earliest[v]:
            earliest[v]=t; pred[v]=idx
changed=True
while changed:
    changed=False
    for idx,(u,v,t) in enumerate(E):
        if u in earliest:
            tr=earliest[u]
            if tr < t <= tr+max_gap:
                if v not in earliest or t<earliest[v]:
                    earliest[v]=t; pred[v]=idx; changed=True
print('earliest size', len(earliest))
print('earliest target', earliest.get(target))
print('earliest sample:', list(earliest.items())[:20])
